import torch
import torch.nn as nn
from cutegen.ptx_runtime import PtxModule, i32, u32, i64, u64, f32, f64

PTX_SOURCE = r"""
.version 8.0
.target sm_89
.address_size 64
.extern .shared .align 4 .b8 smem[];
.visible .entry dw_conv2d_k1w(
    .param .u64 x_ptr,
    .param .u64 y_ptr,
    .param .u64 w_ptr,
    .param .u64 b_ptr,
    .param .u32 has_bias,
    .param .u32 N,
    .param .u32 C,
    .param .u32 H,
    .param .u32 W,
    .param .u32 K,
    .param .u32 stride,
    .param .u32 padding,
    .param .u32 dilation,
    .param .u32 H_out,
    .param .u32 W_out,
    .param .u64 total_elems
)
{
    .reg .pred   %p_done, %p_hasb, %p_wvalid, %p_hvalid, %p_loop, %p_valid, %p_fast, %p_hneg, %p_negup, %p_empty, %p_gt, %p_coop, %p_same_n, %p_same_c, %p_same_oh, %p_allwarp, %p_laneok, %p_do, %p_pref, %p_ncoop;
    .reg .b32    %r_tid, %r_ntid, %r_ctaid, %r_nctaid, %r_stride32;
    .reg .b32    %r_hasb, %rN, %rC, %rH, %rW, %rK, %rS, %rP, %rD, %rHo, %rWo;
    .reg .b32    %r_ow, %r_oh, %r_c, %r_n;
    .reg .b32    %r_tmp1, %r_tmp2, %r_tmp3;
    .reg .b32    %r_iw_s, %r_ih_s, %r_hbase_s;
    .reg .b32    %r_kh;
    .reg .b32    %r_idx32, %r_tmpA32, %r_tmpB32;
    .reg .b32    %r_kh_start, %r_kh_end, %r_Hm1;
    .reg .b32    %r_lane, %r_wid, %r_kcount, %r_n0, %r_c0, %r_oh0;
    .reg .b64    %x, %y, %w, %b;
    .reg .b64    %idx, %grid_stride, %total, %tmp64, %tmpA, %tmpB, %tmpC, %limit;
    .reg .b64    %Wo64, %Ho64, %C64;
    .reg .b64    %addr, %addr_w, %addr_y;
    .reg .b64    %base_nc, %off1, %off2, %off3;
    .reg .b64    %addr_x, %step_b;
    .reg .b64    %smem_base, %warp_sbase;
    .reg .f32    %sum, %xval, %wval, %bval;
    // Load parameters
    ld.param.u64   %x, [x_ptr];
    ld.param.u64   %y, [y_ptr];
    ld.param.u64   %w, [w_ptr];
    ld.param.u64   %b, [b_ptr];
    ld.param.u32   %r_hasb, [has_bias];
    ld.param.u32   %rN, [N];
    ld.param.u32   %rC, [C];
    ld.param.u32   %rH, [H];
    ld.param.u32   %rW, [W];
    ld.param.u32   %rK, [K];
    ld.param.u32   %rS, [stride];
    ld.param.u32   %rP, [padding];
    ld.param.u32   %rD, [dilation];
    ld.param.u32   %rHo, [H_out];
    ld.param.u32   %rWo, [W_out];
    ld.param.u64   %total, [total_elems];
    // Compute thread id and grid stride
    mov.u32        %r_tid, %tid.x;
    mov.u32        %r_ntid, %ntid.x;
    mov.u32        %r_ctaid, %ctaid.x;
    mov.u32        %r_nctaid, %nctaid.x;
    mad.lo.s32     %r_tmp1, %r_ctaid, %r_ntid, %r_tid;   // gtid = blockIdx.x * blockDim.x + threadIdx.x
    mul.lo.u32     %r_stride32, %r_ntid, %r_nctaid;      // grid stride (32-bit)
    cvt.u64.u32    %idx, %r_tmp1;
    cvt.u64.u32    %grid_stride, %r_stride32;
    // Preload 64-bit versions of dims for div/rem
    cvt.u64.u32    %Wo64, %rWo;
    cvt.u64.u32    %Ho64, %rHo;
    cvt.u64.u32    %C64,  %rC;
    // Determine fast 32-bit decode path
    mov.u64        %limit, 4294967295;
    setp.le.u64    %p_fast, %total, %limit;
$loop:
    setp.ge.u64    %p_done, %idx, %total;
    @%p_done bra   $exit;
    // Decode linear index into (n, c, oh, ow)
    @%p_fast bra   $decode32;
$decode64:
    rem.u64        %tmp64, %idx, %Wo64;              // ow
    cvt.u32.u64    %r_ow, %tmp64;
    div.u64        %tmpA, %idx, %Wo64;               // tmpA = idx / W_out
    rem.u64        %tmp64, %tmpA, %Ho64;             // oh
    cvt.u32.u64    %r_oh, %tmp64;
    div.u64        %tmpB, %tmpA, %Ho64;              // tmpB
    rem.u64        %tmp64, %tmpB, %C64;              // c
    cvt.u32.u64    %r_c, %tmp64;
    div.u64        %tmpC, %tmpB, %C64;               // n
    cvt.u32.u64    %r_n, %tmpC;
    bra            $postdecode;
$decode32:
    cvt.u32.u64    %r_idx32, %idx;
    rem.u32        %r_ow, %r_idx32, %rWo;
    div.u32        %r_tmpA32, %r_idx32, %rWo;
    rem.u32        %r_oh, %r_tmpA32, %rHo;
    div.u32        %r_tmpB32, %r_tmpA32, %rHo;
    rem.u32        %r_c, %r_tmpB32, %rC;
    div.u32        %r_n, %r_tmpB32, %rC;
$postdecode:
    // sum initialization (optionally with bias), with warp-broadcasted bias when channel is uniform
    mov.f32        %sum, 0f00000000;
    setp.ne.u32    %p_hasb, %r_hasb, 0;
    @!%p_hasb bra  $post_bias;
    // Determine if all threads in the warp share the same channel to broadcast bias
    mov.u32        %r_tmp1, 0;
    // shfl/vote masks use literal 0xffffffff
    shfl.sync.idx.b32 %r_c0, %r_c, %r_tmp1, 0x1f, 0xffffffff;
    setp.eq.u32    %p_same_c, %r_c, %r_c0;
    vote.sync.all.pred %p_valid, %p_same_c, 0xffffffff;   // p_valid := warp-uniform channel
    // Lane0 will load bias if warp-uniform; others receive via shuffle
    mov.u32        %r_lane, %laneid;
    setp.eq.u32    %p_laneok, %r_lane, 0;
    and.pred       %p_do, %p_valid, %p_laneok;
    @%p_do mul.wide.u32  %addr, %r_c, 4;
    @%p_do add.s64       %addr, %addr, %b;
    @%p_do ld.global.f32 %bval, [%addr];
    @%p_do mov.b32       %r_tmp1, %bval;
    @%p_valid shfl.sync.idx.b32 %r_tmp1, %r_tmp1, 0, 0x1f, 0xffffffff;
    @%p_valid mov.b32        %bval, %r_tmp1;
    @!%p_valid mul.wide.u32  %addr, %r_c, 4;
    @!%p_valid add.s64       %addr, %addr, %b;
    @!%p_valid ld.global.f32 %bval, [%addr];
    mov.f32        %sum, %bval;
  $post_bias:
    mul.lo.s32     %r_tmp1, %r_ow, %rS;
    sub.s32        %r_iw_s, %r_tmp1, %rP;
    // Check iw within [0, W)
    setp.ge.s32    %p_wvalid, %r_iw_s, 0;
    @%p_wvalid setp.lt.s32 %p_wvalid, %r_iw_s, %rW;
    // Precompute hbase = oh * stride - padding
    mul.lo.s32     %r_tmp2, %r_oh, %rS;
    sub.s32        %r_hbase_s, %r_tmp2, %rP;
    // If w is invalid, no valid contributions exist for any kh (kernel width = 1)
    @!%p_wvalid bra $kexit;
    // Precompute base_nc = n*C + c (64-bit)
    mul.wide.u32   %base_nc, %r_n, %rC;          // n*C
    cvt.u64.u32    %tmp64, %r_c;
    add.s64        %base_nc, %base_nc, %tmp64;     // n*C + c
    // Precompute iw (as u32) for addressing when valid
    cvt.u32.s32    %r_tmp1, %r_iw_s;             // iw (u32)
    // Precompute w base offset for channel: c*K
    mul.wide.u32   %addr_w, %r_c, %rK;           // c*K
    // Compute trimmed kh iteration range: kh in [kh_start, kh_end]
    // kh_start = max(0, ceil_div(-hbase, D))
    mov.s32        %r_kh_start, 0;
    setp.lt.s32    %p_hneg, %r_hbase_s, 0;
    @%p_hneg neg.s32  %r_tmp2, %r_hbase_s;          // -hbase
    @%p_hneg add.s32  %r_tmp2, %r_tmp2, %rD;        // -hbase + D
    @%p_hneg add.s32  %r_tmp2, %r_tmp2, -1;         // -hbase + D - 1
    @%p_hneg div.s32  %r_kh_start, %r_tmp2, %rD;    // ceil_div
    // up_num = (H-1) - hbase; if up_num < 0 => no valid kh
    add.s32        %r_Hm1, %rH, -1;
    sub.s32        %r_tmp3, %r_Hm1, %r_hbase_s;     // up_num
    setp.lt.s32    %p_negup, %r_tmp3, 0;
    @%p_negup bra  $kexit;
    // kh_end = min(K-1, up_num / D)
    div.s32        %r_kh_end, %r_tmp3, %rD;
    add.s32        %r_tmp3, %rK, -1;
    setp.gt.s32    %p_gt, %r_kh_end, %r_tmp3;
    @%p_gt mov.s32 %r_kh_end, %r_tmp3;
    // If kh_start >= K or kh_start > kh_end => empty range
    setp.ge.s32    %p_empty, %r_kh_start, %rK;
    @%p_empty bra  $kexit;
    setp.gt.s32    %p_empty, %r_kh_start, %r_kh_end;
    @%p_empty bra  $kexit;
    // Prepare starting ih, input and weight addresses, and loop increments
    mul.lo.s32     %r_tmp2, %r_kh_start, %rD;      // kh_start * D
    add.s32        %r_ih_s, %r_hbase_s, %r_tmp2;   // ih0
    // base_img = ((n*C + c) * H) * W + iw
    cvt.u64.u32    %tmp64, %rH;
    mul.lo.u64     %off1, %base_nc, %tmp64;        // base_nc * H
    cvt.u64.u32    %tmp64, %rW;
    mul.lo.u64     %off1, %off1, %tmp64;           // (base_nc * H) * W
    cvt.u64.u32    %tmp64, %r_tmp1;                // iw
    add.s64        %off1, %off1, %tmp64;           // base_img
    // addr_x = (((... + ih0) * W) + iw) * 4 + x
    cvt.u64.s32    %tmp64, %r_ih_s;
    cvt.u64.u32    %tmpA, %rW;
    mul.lo.u64     %tmpB, %tmp64, %tmpA;           // ih0 * W
    add.s64        %tmpB, %tmpB, %off1;            // elem index
    shl.b64        %addr_x, %tmpB, 2;
    add.s64        %addr_x, %addr_x, %x;
    // step_b = (D * W) * 4 bytes
    mul.wide.u32   %tmp64, %rW, %rD;               // 64-bit D*W
    shl.b64        %step_b, %tmp64, 2;
    // weight address start: addr_w = &w[c,0,kh_start,0]
    cvt.u64.u32    %tmpA, %r_kh_start;
    add.s64        %tmp64, %addr_w, %tmpA;         // c*K + kh_start
    shl.b64        %addr, %tmp64, 2;
    add.s64        %addr_w, %addr, %w;             // reuse %addr_w as byte pointer
    // Compute kh_count and warp info for cooperative weight caching
    add.s32        %r_kcount, %r_kh_end, 1;
    sub.s32        %r_kcount, %r_kcount, %r_kh_start;
    mov.u32        %r_lane, %laneid;
    shr.u32        %r_wid, %r_tid, 5;
    // Broadcast lane0 (n,c,oh) and check warp-uniformity
    mov.u32        %r_tmp1, 0;
    // use literal full mask for shfl/vote
    shfl.sync.idx.b32 %r_n0,  %r_n,  %r_tmp1, 0x1f, 0xffffffff;
    shfl.sync.idx.b32 %r_c0,  %r_c,  %r_tmp1, 0x1f, 0xffffffff;
    shfl.sync.idx.b32 %r_oh0, %r_oh, %r_tmp1, 0x1f, 0xffffffff;
    setp.eq.u32    %p_same_n, %r_n, %r_n0;
    setp.eq.u32    %p_same_c, %r_c, %r_c0;
    and.pred       %p_same_n, %p_same_n, %p_same_c;
    setp.eq.u32    %p_same_oh, %r_oh, %r_oh0;
    and.pred       %p_coop, %p_same_n, %p_same_oh;
    vote.sync.all.pred %p_allwarp, %p_coop, 0xffffffff;
    mov.pred       %p_coop, %p_allwarp;
    // Compute per-warp shared memory base: smem_base + wid*(K*4)
    mov.u64        %smem_base, smem;
    cvt.u64.u32    %tmpA, %rK;
    shl.b64        %tmpA, %tmpA, 2;
    cvt.u64.u32    %tmpB, %r_wid;
    mul.lo.u64     %tmpB, %tmpB, %tmpA;
    add.s64        %warp_sbase, %smem_base, %tmpB;
    // Cooperative load of weights into shared for this warp if uniform
    setp.lt.u32    %p_laneok, %r_lane, %r_kcount;
    and.pred       %p_do, %p_coop, %p_laneok;
    @%p_do cvt.u64.u32 %tmpA, %r_lane;
    @%p_do shl.b64      %tmpA, %tmpA, 2;
    @%p_do add.s64      %tmpA, %tmpA, %addr_w;      // global addr for weight[kh_start + lane]
    @%p_do ld.global.f32 %wval, [%tmpA];
    @%p_do cvt.u64.u32 %tmpB, %r_lane;
    @%p_do shl.b64      %tmpB, %tmpB, 2;
    @%p_do add.s64      %tmpB, %tmpB, %warp_sbase;  // shared addr
    @%p_do st.shared.f32 [%tmpB], %wval;
     @%p_coop bar.warp.sync 0xffffffff;
    // Loop over kernel height kh from kh_start to kh_end
    // Unrolled accumulation over kh in steps of 2 with pointer increments
    // r_kcount already computed; process pairs then tail
    mov.u32        %r_tmp1, %r_kcount;
    setp.le.s32    %p_loop, %r_tmp1, 0;
    @%p_loop bra   $kexit;
    // Initialize weight pointer depending on cooperative caching
    @%p_coop mov.b64   %tmpA, %warp_sbase;
    @!%p_coop mov.b64  %tmpA, %addr_w;
    // step_x2 = 2 * step_b
    shl.b64        %tmpB, %step_b, 1;
$kloop_pair:
    setp.ge.s32    %p_loop, %r_tmp1, 2;
    @!%p_loop bra  $kloop_tail;
    // Prefetch next pair's input and weights into L2 if another pair remains
    setp.ge.s32    %p_pref, %r_tmp1, 4;
    @%p_pref add.s64 %off3, %addr_x, %tmpB;
    @%p_pref prefetch.global.L2 [%off3];
    not.pred       %p_ncoop, %p_coop;
    and.pred       %p_do, %p_pref, %p_ncoop;
    @%p_do add.s64 %off3, %tmpA, 8;
    @%p_do prefetch.global.L2 [%off3];
    // First of the pair
    ld.global.f32  %xval, [%addr_x];
    @%p_coop ld.shared.f32  %wval, [%tmpA];
    @!%p_coop ld.global.f32 %wval, [%tmpA];
    fma.rn.f32     %sum, %xval, %wval, %sum;
    // Second of the pair
    add.s64        %off1, %addr_x, %step_b;
    ld.global.f32  %xval, [%off1];
    @%p_coop add.s64 %off2, %tmpA, 4;
    @%p_coop ld.shared.f32 %wval, [%off2];
    @!%p_coop add.s64 %off2, %tmpA, 4;
    @!%p_coop ld.global.f32 %wval, [%off2];
    fma.rn.f32     %sum, %xval, %wval, %sum;
    // Advance pointers and decrement remaining
    add.s64        %addr_x, %addr_x, %tmpB;
    add.s64        %tmpA, %tmpA, 8;
    add.s32        %r_tmp1, %r_tmp1, -2;
    bra            $kloop_pair;
$kloop_tail:
    // Process remaining single iteration if any
    setp.eq.s32    %p_loop, %r_tmp1, 1;
    @!%p_loop bra  $kexit;
    ld.global.f32  %xval, [%addr_x];
    @%p_coop ld.shared.f32  %wval, [%tmpA];
    @!%p_coop ld.global.f32 %wval, [%tmpA];
    fma.rn.f32     %sum, %xval, %wval, %sum;
$kexit:
    // Store output at y[idx]
    shl.b64         %addr_y, %idx, 2;
    add.s64         %addr_y, %addr_y, %y;
    st.global.f32   [%addr_y], %sum;
    // Next element
    add.u64         %idx, %idx, %grid_stride;
    bra             $loop;
$exit:
    ret;
}
"""

_ptx_module = None

def _get_ptx_module():
    global _ptx_module
    if _ptx_module is None:
        _ptx_module = PtxModule(PTX_SOURCE)
    return _ptx_module

def validate_generated_code():
    # Force PTX JIT assembly and entry-point lookup during compile validation.
    _get_ptx_module().function("dw_conv2d_k1w")

class ModelNew(nn.Module):
    """
    Performs a depthwise 2D convolution with a square input and an asymmetric kernel using a custom PTX kernel.
    """
    def __init__(self, in_channels: int, kernel_size: int, stride: int = 1, padding: int = 0, dilation: int = 1, bias: bool = False):
        super().__init__()
        self.in_channels = in_channels
        self.kernel_size = kernel_size
        self.stride = stride
        self.padding = padding
        self.dilation = dilation
        # Initialize parameters identically to nn.Conv2d with groups=in_channels, kernel_size=(kernel_size,1)
        conv_ref = nn.Conv2d(in_channels, in_channels, kernel_size=(kernel_size, 1),
                             stride=stride, padding=padding, dilation=dilation,
                             groups=in_channels, bias=bias)
        self.weight = nn.Parameter(conv_ref.weight.detach().clone())
        if bias:
            self.bias = nn.Parameter(conv_ref.bias.detach().clone())
        else:
            self.bias = None

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        assert x.dim() == 4, "Input must be NCHW"
        assert x.size(1) == self.in_channels, "Channel mismatch"
        x = x.contiguous()
        N, C, H, W = x.shape
        K = self.kernel_size
        S = int(self.stride)
        P = int(self.padding)
        D = int(self.dilation)

        # Output dimensions following PyTorch Conv2d formula
        H_out = (H + 2 * P - D * (K - 1) - 1) // S + 1
        W_out = (W + 2 * P - D * (1 - 1) - 1) // S + 1  # kernel width is 1
        out = torch.empty((N, C, H_out, W_out), device=x.device, dtype=x.dtype)

        # Launch PTX kernel
        total = out.numel()
        block_x = 256
        grid_x = (total + block_x - 1) // block_x
        module = _get_ptx_module()
        b_tensor = self.bias if self.bias is not None else x  # valid pointer even if unused
        module.launch(
            "dw_conv2d_k1w",
            grid=(int(grid_x), 1, 1),
            block=(int(block_x), 1, 1),
            arguments=[
                x, out, self.weight, b_tensor,
                i32(1 if self.bias is not None else 0),
                i32(N), i32(C), i32(H), i32(W),
                i32(K), i32(S), i32(P), i32(D),
                i32(H_out), i32(W_out),
                u64(total),
            ],
            shared_memory=int(((block_x + 31) // 32) * K * 4),
            stream=torch.cuda.current_stream(x.device),
        )
        return out

