    mul.lo.u64     %off1, %base_nc, %tmp64;        // base_nc * H
    cvt.u64.u32    %tmp64, %rW;
    mul.lo.u64     %off1, %off1, %tmp64;           // (base_nc * H) * W
    cvt.u64.u32    %tmp64, %r_tmp1;                // iw
    add.s64        %off1, %off1, %tmp64;           // base_img
    // addr_x = (((... + ih0) * W) + iw) * 4 + x
    cvt.u64.s32    %tmp64, %r_ih_s;
    cvt.u64.u32    %tmpA, %rW;
    mul.lo.u64     %tmpB, %tmp64, %tmpA;           // ih0 * W
    add.s64        %tmpB, %tmpB, %off1;            // elem index
    shl.b64        %addr_x, %tmpB, 2;
    add.s64        %addr_x, %addr_x, %x;
    // step_b = (D * W) * 4 bytes
    mul.wide.u32   %tmp64, %rW, %rD;               // 64-bit D*W
    shl.b64        %step_b, %tmp64, 2;
    // weight address start: addr_w = &w[c,0,kh_start,0]
    cvt.u64.u32    %tmpA, %r_kh_start;
    add.s64        %tmp64, %addr_w, %tmpA;         // c*K + kh_start
    shl.b64        %addr, %tmp64, 2;
    add.s64        %addr_w, %addr, %w;             // reuse %addr_w as byte pointer
    // Loop over kernel height kh from kh_start to kh_end
    mov.u32        %r_kh, %r_kh_start;
$kloop:
    setp.gt.s32    %p_loop, %r_kh, %r_kh_end;
    @%p_loop bra   $kexit;
    // Load input and weight, accumulate
    ld.global.f32  %xval, [%addr_x];
    ld.global.f32  %wval, [%addr_w];
    fma.rn.f32     %sum, %xval, %wval, %sum;
    // Advance pointers
    add.s64        %addr_x, %addr_x, %step_b;
    add.s64        %addr_w, %addr_w, 4;
    add.s32        %r_kh, %r_kh, 1;
    bra            $kloop;
$kexit:
    // Store output at y[idx]
    shl.b64         %addr_y, %idx, 2;
    add.s64         %addr_y, %addr_y, %y;
    st.global.f32   [%addr_y], %sum;
    // Next element
    add.u64         %idx, %idx, %grid_stride;
    bra             $loop;
$exit:
    ret;
}
"""

_ptx_module = None

def _get_ptx_module():
    global _ptx_module
    if _ptx_module is None:
        _ptx_module = PtxModule(PTX_SOURCE)
    return _ptx_module

def validate_generated_code():
    # Force PTX JIT assembly and entry-point lookup during compile validation.
    _get_ptx_module().function("dw_conv2d_k1w")

class ModelNew(nn.Module):
    """
    Performs a depthwise 2D convolution with a square input and an asymmetric kernel using a custom PTX kernel.
    """
    def __init__(self, in_channels: int, kernel_size: int, stride: int = 1, padding: int = 0, dilation: int = 1, bias: bool = False):
        super().__init__()
        self.in_channels = in_channels
        self.kernel_size = kernel_size
        self.stride = stride
        self.padding = padding
        self.dilation = dilation
        # Initialize parameters identically to nn.Conv2d with groups=in_channels, kernel_size=(kernel_size,1)
        conv_ref = nn.Conv2d(in_channels, in_channels, kernel_size=(kernel_size, 1),
                             stride=stride, padding=padding, dilation=dilation,
                             groups=in_channels, bias=bias)
        self.weight = nn.Parameter(conv_ref.weight.detach().clone())
        if bias:
            self.bias = nn.Parameter(conv_ref.bias.detach().clone())
        else:
            self.bias = None

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        assert x.dim() == 4, "Input must be NCHW"
        assert x.size(1) == self.in_channels, "Channel mismatch"
        x = x.contiguous()
        N, C, H, W = x.shape
        K = self.kernel_size
        S = int(self.stride)
        P = int(self.padding)
        D = int(self.dilation)

        # Output dimensions following PyTorch Conv2d formula
        H_out = (H + 2 * P - D * (K - 1) - 1) // S + 1
        W_out = (W + 2 * P - D * (1 - 1) - 1) // S + 1  # kernel width is 1
        out = torch.empty((N, C, H_out, W_out), device=x.device, dtype=x.dtype)

        # Launch PTX kernel
        total = out.numel()
        block_x = 256
        grid_x = (total + block_x - 1) // block_x
        module = _get_ptx_module()
        b_tensor = self.bias if self.bias is not None else x  # valid pointer even if unused
        module.launch(
            "dw_conv2d_k1w",
            grid=(int(grid_x), 1, 1),
            block=(int(block_x), 1, 1),
            arguments=[
                x, out, self.weight, b_tensor,
                i32(1 if self.bias is not None else 0),
                i32(N), i32(C), i32(H), i32(W),
                i32(K), i32(S), i32(P), i32(D),
                i32(H_out), i32(W_out),
                u64(total),
            ],
            shared_memory=0,
            stream=torch.cuda.current_stream(x.device),
        )
        return out
